<script setup lang="ts">
import { Link, useForm } from '@inertiajs/vue3';
import { computed } from 'vue';
import type { BranchOption, TreasuryAccountOption, TreasuryTransferDetail } from '@/Types/treasury';

const props = defineProps<{ branches: BranchOption[]; accounts: TreasuryAccountOption[]; defaults: { transfer_date: string; posting_date: string; currency_code: string; exchange_rate: string }; document?: TreasuryTransferDetail }>();
const form = useForm({ source_branch_id: props.document?.source_branch_id ?? null as number | null, destination_branch_id: props.document?.destination_branch_id ?? null as number | null, source_account_id: props.document?.source_account_id ?? null as number | null, destination_account_id: props.document?.destination_account_id ?? null as number | null, transfer_date: props.document?.transfer_date ?? props.defaults.transfer_date, posting_date: props.document?.posting_date ?? props.defaults.posting_date, currency_code: props.document?.currency_code ?? props.defaults.currency_code, exchange_rate: props.document?.exchange_rate ?? props.defaults.exchange_rate, amount: props.document?.amount ?? '', reference: props.document?.reference ?? '', notes: props.document?.notes ?? '' });
const baseAmount = computed(() => Number(form.amount || 0) * Number(form.exchange_rate || 0));
const submit = (): void => { if (props.document) form.put(route('treasury-transfers.update', props.document.id)); else form.post(route('treasury-transfers.store')); };
</script>
<template><form class="space-y-6" @submit.prevent="submit"><div class="rounded-2xl border border-gray-200 bg-white p-6 dark:border-gray-800 dark:bg-gray-900"><h2 class="text-lg font-semibold">Transfer Details</h2><div class="mt-5 grid gap-5 md:grid-cols-2 xl:grid-cols-4"><label class="space-y-1 text-sm">Source Branch<select v-model="form.source_branch_id" class="h-11 w-full rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700"><option :value="null">Select</option><option v-for="b in branches" :key="b.id" :value="b.id">{{ b.name }}</option></select><span class="text-xs text-error-500">{{ form.errors.source_branch_id }}</span></label><label class="space-y-1 text-sm">Source Account<select v-model="form.source_account_id" class="h-11 w-full rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700"><option :value="null">Select</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.code }} — {{ a.name }} ({{ a.control_type }})</option></select><span class="text-xs text-error-500">{{ form.errors.source_account_id }}</span></label><label class="space-y-1 text-sm">Destination Branch<select v-model="form.destination_branch_id" class="h-11 w-full rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700"><option :value="null">Select</option><option v-for="b in branches" :key="b.id" :value="b.id">{{ b.name }}</option></select><span class="text-xs text-error-500">{{ form.errors.destination_branch_id }}</span></label><label class="space-y-1 text-sm">Destination Account<select v-model="form.destination_account_id" class="h-11 w-full rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700"><option :value="null">Select</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.code }} — {{ a.name }} ({{ a.control_type }})</option></select><span class="text-xs text-error-500">{{ form.errors.destination_account_id }}</span></label><label class="space-y-1 text-sm">Transfer Date<input v-model="form.transfer_date" type="date" class="h-11 w-full rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700"/><span class="text-xs text-error-500">{{ form.errors.transfer_date }}</span></label><label class="space-y-1 text-sm">Posting Date<input v-model="form.posting_date" type="date" class="h-11 w-full rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700"/><span class="text-xs text-error-500">{{ form.errors.posting_date }}</span></label><label class="space-y-1 text-sm">Currency<input v-model="form.currency_code" maxlength="3" class="h-11 w-full rounded-lg border border-gray-300 bg-transparent px-3 uppercase dark:border-gray-700"/></label><label class="space-y-1 text-sm">Exchange Rate<input v-model="form.exchange_rate" type="number" min="0.00000001" step="0.00000001" class="h-11 w-full rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700"/></label><label class="space-y-1 text-sm">Amount<input v-model="form.amount" type="number" min="0.000001" step="0.000001" class="h-11 w-full rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700"/><span class="text-xs text-error-500">{{ form.errors.amount }}</span></label><label class="space-y-1 text-sm">Base Amount<input :value="baseAmount.toFixed(6)" readonly class="h-11 w-full rounded-lg border border-gray-300 bg-gray-50 px-3 dark:border-gray-700 dark:bg-gray-800"/></label><label class="space-y-1 text-sm md:col-span-2">Reference<input v-model="form.reference" maxlength="160" class="h-11 w-full rounded-lg border border-gray-300 bg-transparent px-3 dark:border-gray-700"/></label><label class="space-y-1 text-sm md:col-span-2 xl:col-span-4">Notes<textarea v-model="form.notes" rows="4" maxlength="4000" class="w-full rounded-lg border border-gray-300 bg-transparent p-3 dark:border-gray-700"/></label></div></div><div class="flex justify-end gap-3"><Link :href="document ? route('treasury-transfers.show', document.id) : route('treasury-transfers.index')" class="rounded-lg border border-gray-300 px-5 py-2.5 text-sm dark:border-gray-700">Cancel</Link><button :disabled="form.processing" class="rounded-lg bg-brand-500 px-5 py-2.5 text-sm font-medium text-white disabled:opacity-50" type="submit">{{ form.processing ? 'Saving...' : document ? 'Update Draft' : 'Create Draft' }}</button></div></form></template>
